import heapq

def nearest_stations(stations, k):
    heap = []
    for x, y in stations:
        d = x * x + y * y
        heapq.heappush(heap, (-d, x, y))
        if len(heap) > k:
            heapq.heappop(heap)
    return [[x, y] for _, x, y in heap]

