import java.util.*;

class Solution {
    public int[][] nearestStations(int[][] stations, int k) {
        // A max-heap on distance holds the k nearest seen so far.
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Long.compare(dist(b), dist(a)));
        for (int[] s : stations) {
            heap.add(s);
            if (heap.size() > k) heap.poll();
        }
        int[][] out = new int[heap.size()][];
        int i = 0;
        for (int[] s : heap) out[i++] = new int[]{s[0], s[1]};
        return out;
    }

    private long dist(int[] p) {
        return (long) p[0] * p[0] + (long) p[1] * p[1];
    }
}

